lessons[0].sources.push(source('PowerShell: process objects and memory properties','https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.management/get-process?view=powershell-7.5'));
lessons[1].sources.push(source('Microsoft: configured DNS client servers','https://learn.microsoft.com/en-us/powershell/module/dnsclient/get-dnsclientserveraddress?view=windowsserver2025-ps'));
lessons[1].sources.push(source('Microsoft: DNS and directory-service discovery','https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/dns-and-ad-ds'));
